package com.bananalab.lite;
import java.io.*;import java.util.*;
public class Stage35ModelsCheck{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{String root=args[0];PixelGenerator pixel=new PixelGenerator(new FileInputStream(root+"/assets/pixel-v2/character21.bin"));check(pixel.inputs==48&&pixel.hidden==256,"Pixel21 architecture");float max=0;try(DataInputStream in=new DataInputStream(new FileInputStream(root+"/model-source/pixel21-reference.bin"))){int rows=in.readInt(),n=in.readInt();for(int i=0;i<rows;i++){float[] input=new float[n];for(int j=0;j<n;j++)input[j]=in.readFloat();float[] result=pixel.forward(input);for(int j=0;j<4;j++)max=Math.max(max,Math.abs(result[j]-in.readFloat()));}}check(max<.0004,"pixel parity");System.out.println("PIXEL21_PARITY "+max);
 BananaTransformer chat=new BananaTransformer(new FileInputStream(root+"/assets/chat34/chat34.bin"),new FileInputStream(root+"/assets/chat34/vocab.txt"),new FileInputStream(root+"/assets/chat34/tokenizer.json"));check(chat.d==128&&chat.layers==3,"Chat34 architecture");float error=0;try(DataInputStream in=new DataInputStream(new FileInputStream(root+"/model-source/chat34-reference.bin"))){int cases=in.readInt(),v=in.readInt();for(int i=0;i<cases;i++){int n=in.readInt();BananaTransformer.Session session=chat.session();float[] actual=null;for(int j=0;j<n;j++)actual=session.step(in.readInt());for(int j=0;j<v;j++)error=Math.max(error,Math.abs(actual[j]-in.readFloat()));}}check(error<.0004,"chat parity");System.out.println("CHAT34_PARITY "+error);

 for(String component:new String[]{"tomato22","faces22","background22","vision22"}){String asset=component.equals("tomato22")?"pixel-v2/tomato22.bin":component.equals("background22")?"background/background22.bin":"pixel22/"+component+".bin";Object net=component.equals("background22")?new BackdropField(new FileInputStream(root+"/assets/"+asset)):component.equals("vision22")?new OwnVision(new FileInputStream(root+"/assets/"+asset)):new PixelGenerator(new FileInputStream(root+"/assets/"+asset));float err=0;try(DataInputStream in=new DataInputStream(new FileInputStream(root+"/model-source/"+component+"-reference.bin"))){int rows=in.readInt(),n=in.readInt();for(int row=0;row<rows;row++){float[] x=new float[n];for(int i=0;i<n;i++)x[i]=in.readFloat();float[] y=net instanceof PixelGenerator?((PixelGenerator)net).forward(x):net instanceof BackdropField?((BackdropField)net).forward(x):((OwnVision)net).forward(x);for(int i=0;i<y.length;i++)err=Math.max(err,Math.abs(y[i]-in.readFloat()));}}check(err<.0005,component+" parity "+err);System.out.println(component+" PARITY "+err);}
 for(String name:new String[]{"celia","ramiro","olivia","raquel","dario"}){List<String[]> history=Arrays.asList(new String[]{"crea un gato llamado "+name,"el personaje se llama "+name+" ."},new String[]{"su color es azul",name+" es azul ."},new String[]{"lleva sobretodo","conservo su identidad y agrego el sobretodo ."});System.out.println("RESERVED_NAME "+name+" => "+chat.generate("como se llama",history).text);}
 for(String q:new String[]{"hola","sos independiente","que significa entregar","quiero una idea de detectives"})System.out.println("CHAT "+q+" => "+chat.generate(q,"","").text);
 }
}
